-- HOLBERY Commerce OS v0 — Cloudflare D1 / SQLite
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS brands (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL,slug TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',UNIQUE(organization_id,slug));
CREATE TABLE IF NOT EXISTS storefronts (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),brand_id TEXT NOT NULL REFERENCES brands(id),name TEXT NOT NULL,slug TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'direct',status TEXT NOT NULL DEFAULT 'active',UNIQUE(organization_id,slug));
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),brand_id TEXT NOT NULL REFERENCES brands(id),storefront_id TEXT REFERENCES storefronts(id),type TEXT NOT NULL DEFAULT 'physical',name TEXT NOT NULL,slug TEXT NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'draft',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(brand_id,slug));
CREATE TABLE IF NOT EXISTS product_variants (id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),sku TEXT,name TEXT NOT NULL,price_idr INTEGER NOT NULL,stock INTEGER,status TEXT NOT NULL DEFAULT 'active',UNIQUE(product_id,sku));
CREATE TABLE IF NOT EXISTS customers (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),email TEXT,phone TEXT,name TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS carts (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),storefront_id TEXT NOT NULL REFERENCES storefronts(id),customer_id TEXT REFERENCES customers(id),status TEXT NOT NULL DEFAULT 'open',currency TEXT NOT NULL DEFAULT 'IDR',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cart_items (id TEXT PRIMARY KEY,cart_id TEXT NOT NULL REFERENCES carts(id),variant_id TEXT NOT NULL REFERENCES product_variants(id),quantity INTEGER NOT NULL CHECK(quantity > 0),unit_price_idr INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),brand_id TEXT NOT NULL REFERENCES brands(id),storefront_id TEXT NOT NULL REFERENCES storefronts(id),customer_id TEXT REFERENCES customers(id),status TEXT NOT NULL DEFAULT 'pending_payment',payment_status TEXT NOT NULL DEFAULT 'unpaid',fulfillment_status TEXT NOT NULL DEFAULT 'unfulfilled',currency TEXT NOT NULL DEFAULT 'IDR',subtotal_idr INTEGER NOT NULL,shipping_idr INTEGER NOT NULL DEFAULT 0,discount_idr INTEGER NOT NULL DEFAULT 0,total_idr INTEGER NOT NULL,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,idempotency_key));
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),variant_id TEXT REFERENCES product_variants(id),product_name TEXT NOT NULL,variant_name TEXT,quantity INTEGER NOT NULL CHECK(quantity > 0),unit_price_idr INTEGER NOT NULL,line_total_idr INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),provider TEXT NOT NULL,provider_reference TEXT,merchant_order_id TEXT NOT NULL UNIQUE,amount_idr INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'created',payment_url TEXT,raw_reference TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payment_events (id TEXT PRIMARY KEY,payment_id TEXT REFERENCES payments(id),provider TEXT NOT NULL,provider_event_id TEXT,event_type TEXT NOT NULL,result_code TEXT,signature_valid INTEGER NOT NULL DEFAULT 0,payload_json TEXT NOT NULL,received_at TEXT NOT NULL,UNIQUE(provider,provider_event_id));
CREATE TABLE IF NOT EXISTS fulfillments (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),status TEXT NOT NULL DEFAULT 'pending',method TEXT,tracking_reference TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS commerce_events (id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),brand_id TEXT,storefront_id TEXT,aggregate_type TEXT NOT NULL,aggregate_id TEXT NOT NULL,event_type TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_products_storefront ON products(storefront_id,status);
CREATE INDEX IF NOT EXISTS idx_variants_product ON product_variants(product_id,status);
CREATE INDEX IF NOT EXISTS idx_orders_storefront ON orders(storefront_id,created_at);
CREATE INDEX IF NOT EXISTS idx_orders_payment ON orders(payment_status,status);
CREATE INDEX IF NOT EXISTS idx_payments_order ON payments(order_id);
CREATE INDEX IF NOT EXISTS idx_payment_events_payment ON payment_events(payment_id,received_at);
CREATE INDEX IF NOT EXISTS idx_events_aggregate ON commerce_events(aggregate_type,aggregate_id,created_at);
